"""Legacy Meridian CRM numeric division compatibility."""

from __future__ import annotations


def _numeric(value: object) -> float:
    """Apply legacy numeric coercion for supported CRMScript operands."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """
    Divide using Meridian CRM CRMScript semantics.

    A divisor that coerces to zero returns 0.0 and emits SCRIPT_DIV0.
    """
    numerator = _numeric(a)
    divisor = _numeric(b)

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / divisor, []
    except (ArithmeticError, OverflowError):
        return 0.0, ["SCRIPT_DIV0"]
